rust_translation:
fn analyze_apply_if_condition(&self, arrow_fn: &ArrowExpr) -> ApplyIfResult {
    // Get first param name, default to 'ctx'
    let param = arrow_fn.params.get(0);
    let param_name = param
        .and_then(|p| match p {
            Pat::Ident(ident) => Some(ident.id.sym.to_string()),
            _ => None,
        })
        .unwrap_or_else(|| "ctx".to_string());

    // Generate C# from body
    let csharp_condition = match &*arrow_fn.body {
        BlockStmtOrExpr::Expr(expr) => self.generate_csharp_from_expression(expr, &param_name),
        BlockStmtOrExpr::BlockStmt(block) => self.generate_csharp_from_block(block, &param_name),
    };

    ApplyIfResult {
        csharp_code: format!("{} => {}", param_name, csharp_condition),
        result_type: "arrow".to_string(),
    }
}
